//! Fixed admitted erasure DB sequence. No identity, preferences or network access.
#[derive(Debug,PartialEq,Eq)]pub enum Error<E>{Callback(E)}
pub trait Backend{type Error;fn ready(&mut self)->Result<(),Self::Error>;fn global(&mut self,i:i32)->Result<(),Self::Error>;fn owned(&mut self,i:i32)->Result<(),Self::Error>;fn receipts(&mut self)->Result<(),Self::Error>;fn exists(&mut self,i:i32)->Result<bool,Self::Error>;fn stage_delete(&mut self,i:i32)->Result<(),Self::Error>;fn defaults(&mut self)->Result<(),Self::Error>;}
pub fn execute<B:Backend>(b:&mut B)->Result<(),Error<B::Error>>{b.ready().map_err(Error::Callback)?;for i in 0..4{b.global(i).map_err(Error::Callback)?;}for i in 0..4{b.owned(i).map_err(Error::Callback)?;}b.receipts().map_err(Error::Callback)?;for i in 0..3{if b.exists(i).map_err(Error::Callback)?{b.stage_delete(i).map_err(Error::Callback)?;}}b.defaults().map_err(Error::Callback)?;Ok(())}
#[cfg(test)]mod tests{use super::*;struct P{trace:Vec<String>,mask:u8,cut:usize}impl P{fn hit(&mut self,s:String)->Result<(),usize>{self.trace.push(s);if self.trace.len()==self.cut{Err(self.cut)}else{Ok(())}}}impl Backend for P{type Error=usize;fn ready(&mut self)->Result<(),usize>{self.hit("ready".into())}fn global(&mut self,i:i32)->Result<(),usize>{self.hit(format!("global{i}"))}fn owned(&mut self,i:i32)->Result<(),usize>{self.hit(format!("owned{i}"))}fn receipts(&mut self)->Result<(),usize>{self.hit("receipts".into())}fn exists(&mut self,i:i32)->Result<bool,usize>{self.hit(format!("exists{i}"))?;Ok(self.mask&(1<<i)!=0)}fn stage_delete(&mut self,i:i32)->Result<(),usize>{self.hit(format!("stage{i}"))}fn defaults(&mut self)->Result<(),usize>{self.hit("defaults".into())}}
#[test]fn all_eight_optional_shapes_exact_order_every_error_cutoff(){for mask in 0..8{let mut p=P{trace:vec![],mask,cut:0};assert_eq!(execute(&mut p),Ok(()));let mut expected=vec!["ready".to_string()];for i in 0..4{expected.push(format!("global{i}"));}for i in 0..4{expected.push(format!("owned{i}"));}expected.push("receipts".into());for i in 0..3{expected.push(format!("exists{i}"));if mask&(1<<i)!=0{expected.push(format!("stage{i}"));}}expected.push("defaults".into());assert_eq!(p.trace,expected);for cut in 1..=expected.len(){let mut p=P{trace:vec![],mask,cut};assert_eq!(execute(&mut p),Err(Error::Callback(cut)));assert_eq!(p.trace,expected[..cut]);}}}}
